# METADATA
# title: ÖPUL 2023 – Humuserhalt und Bodenschutz auf umbruchsfähigem Grünland (o6_17) – gemeinsame Hilfsregeln
# description: >-
#   Gemeinsame Eingaben, Datentabellen und Hilfsfunktionen für die Maßnahme
#   o6_17 (Intervention 70-15). Alle Tabellen stammen aus data/o6_17/*.json.
package oepul.o6_17

# Datentabellen der Maßnahme (data/o6_17/*.json)
cfg := data.o6_17

# Antragsjahr (Kalenderjahr der Umsetzung, § 21 Abs. 5 GSP-AV)
application_year := input.farm.year

# Maßnahmenspezifische Angaben (vorgeschlagener Profilzweig oepul.o6_17)
o617 := object.get(input, ["oepul", "o6_17"], {})

# Optionaler Bewertungsstichtag (vorgeschlagener Profilzweig oepul.evaluation_date)
evaluation_date := object.get(input, ["oepul", "evaluation_date"], null)

participating_measures := {m | some m in object.get(input, ["oepul", "participating_measures"], [])}

parcels := object.get(input, ["land", "parcels"], [])

parcel_codes(p) := {c | some c in object.get(p, "codes", [])}

is_grassland(p) if p.land_use == "grassland"

# Zeile der Schlagnutzungsart (Grünland) aus data/o6_17/lists.json
field_use_row(p) := row if {
	some row in cfg.lists.grassland_field_use_types
	row.key == object.get(p, "field_use_type", "")
}

field_use_attr(p, attr) := row[attr] if {
	row := field_use_row(p)
}

arable_forage_keys := {r.key | some r in cfg.lists.arable_forage_field_uses}

is_arable_forage(p) if {
	p.land_use == "arable"
	object.get(p, "field_use_type", "") in arable_forage_keys
}

# Gültigkeitszeitraum einer Tabellenzeile (from_year/to_year, to_year null = offen)
year_in_range(y, row) if {
	row.from_year <= y
	row.to_year == null
}

year_in_range(y, row) if {
	row.from_year <= y
	is_number(row.to_year)
	y <= row.to_year
}

value_at_least(_, lower) if lower == null

value_at_least(v, lower) if {
	is_number(lower)
	v >= lower
}

value_below(_, upper) if upper == null

value_below(v, upper) if {
	is_number(upper)
	v < upper
}

# Frist abgelaufen: entweder Bewertungsstichtag nach der Frist oder Antragsjahr nach dem Fristjahr
deadline_passed(deadline) if {
	is_string(evaluation_date)
	evaluation_date > deadline
}

deadline_passed(deadline) if {
	not is_string(evaluation_date)
	application_year > to_number(substring(deadline, 0, 4))
}

ubb_or_bio_participation if {
	some m in cfg.lists.combination_obligation_measures
	m in participating_measures
}

# Flächen mit Umbruchsverbot gemäß GLÖZ 2, GLÖZ 4 oder GLÖZ 9
gloez_conversion_ban(p) if {
	some t in cfg.lists.gloez_conversion_ban_types
	object.get(p, ["constraints", "gloez_conversion_ban", t.key], false) == true
}

# Allgemein nicht prämienfähige Flächen (Sonstige Flächen, Grünlandbrachen, Code OP/VF, Nationalparks)
parcel_excluded_general(p) if {
	row := field_use_row(p)
	row.premium_eligible == false
}

parcel_excluded_general(p) if {
	some c in cfg.lists.non_eligible_parcel_codes
	c in parcel_codes(p)
}

parcel_excluded_general(p) if {
	object.get(p, ["constraints", "national_park"], null) in {np | some np in cfg.lists.national_parks_without_area_premiums}
}

parcel_excluded_general(p) if {
	np := object.get(p, ["constraints", "national_park"], null)
	is_string(np)
	object.get(p, ["constraints", "national_park_relevant_restrictions"], false) == true
}

grassland_area_ha := s if {
	count(parcels) > 0
	s := sum([p.area_ha | some p in parcels; is_grassland(p)])
}

grassland_area_ha := object.get(input, ["land", "grassland_area_ha"], 0) if count(parcels) == 0

arable_forage_area_ha := sum([p.area_ha | some p in parcels; is_arable_forage(p)])

# Landwirtschaftliche Nutzfläche ohne Almweideflächen (Annahme: total_area_ha enthält Almweideflächen)
utilised_area_excl_alpine_ha := object.get(input, ["land", "total_area_ha"], 0) - object.get(input, ["land", "alpine_pasture_area_ha"], 0)

# Modul:
#   o6_17 – Zugangs- und Fördervoraussetzungen
package oepul.o6_17

contract_start_year := object.get(o617, "contract_start_year", null)

first_participation_year if application_year == contract_start_year

first_year_min := cfg.general.first_year_minimums

grassland_share := grassland_area_ha / utilised_area_excl_alpine_ha if utilised_area_excl_alpine_ha > 0

combination_obligation_met if ubb_or_bio_participation

# Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr (SRL 1.6.1)
first_oepul_year if application_year == object.get(input, ["oepul", "first_oepul_year"], null)

farm_minimum_size_met if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= cfg.general.farm_minimum_size_first_oepul_year.min_protected_cultivation_ha
}

farm_minimum_size_met if {
	object.get(input, ["land", "total_area_ha"], 0) >= cfg.general.farm_minimum_size_first_oepul_year.min_agricultural_area_ha
}

applicant := object.get(input, ["oepul", "applicant"], {})

applicant_type_eligible if object.get(applicant, "applicant_type", "") in {t | some t in cfg.lists.eligible_applicant_types}

public_body_share_ok if object.get(applicant, "public_body_share", 0) <= cfg.lists.public_body_max_share

contract_period_row := row if {
	some row in cfg.general.contract_periods
	row.start_year == contract_start_year
}

entry_application_deadline := sprintf("%d-12-31", [contract_start_year - 1]) if is_number(contract_start_year)

entry_application_timely if {
	d := object.get(o617, "measure_application_date", null)
	is_string(d)
	d <= entry_application_deadline
}

access_violations contains v if {
	not combination_obligation_met
	v := {"rule_id": "O6_17-MB-3.2-COMBINATION-OBLIGATION", "message": "Keine zeitgleiche Teilnahme an UBB, BIO oder BIO-Teilbetrieb"}
}

access_violations contains v if {
	first_participation_year
	grassland_area_ha < first_year_min.min_grassland_ha
	v := {"rule_id": "O6_17-MB-3.3-MIN-GRASSLAND", "message": sprintf("Grünlandfläche im 1. Teilnahmejahr %v ha < %v ha", [grassland_area_ha, first_year_min.min_grassland_ha])}
}

access_violations contains v if {
	first_participation_year
	not grassland_share_sufficient
	v := {"rule_id": "O6_17-MB-3.3-MIN-GRASSLAND-SHARE", "message": "Grünlandanteil an der LN (ohne Almweideflächen) im 1. Teilnahmejahr unter 40 %"}
}

grassland_share_sufficient if grassland_share >= first_year_min.min_grassland_share_of_utilised_area_excl_alpine

access_violations contains v if {
	first_participation_year
	not is_livestock_farm
	v := {"rule_id": "O6_17-MB-3.4-LIVESTOCK-FIRST-YEAR", "message": "Eigenschaft als tierhaltender Betrieb (>= 0,30 RGVE/ha Futterfläche) im 1. Teilnahmejahr nicht erfüllt"}
}

access_violations contains v if {
	first_oepul_year
	not farm_minimum_size_met
	v := {"rule_id": "O6_17-AT-5.3-FARM-MIN-SIZE", "message": "Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr nicht erreicht"}
}

access_violations contains v if {
	first_participation_year
	not contract_period_row
	v := {"rule_id": "O6_17-MB-7-LAST-ENTRY", "message": "Vertragsbeginn nur 2023, 2024 oder 2025 möglich (letzter Einstieg Förderjahr 2025)"}
}

access_violations contains v if {
	first_participation_year
	not entry_application_timely
	v := {"rule_id": "O6_17-MB-7-APPLICATION-DEADLINE", "message": "Maßnahmenantrag nicht bis 31.12. vor Vertragsbeginn gestellt"}
}

access_violations contains v if {
	not applicant_type_eligible
	v := {"rule_id": "O6_17-AT-5.2-APPLICANT-TYPE", "message": "Förderwerbende Person ist keine zulässige Personenkategorie"}
}

access_violations contains v if {
	not public_body_share_ok
	v := {"rule_id": "O6_17-AT-5.2-PUBLIC-BODY", "message": "Beteiligung von Gebietskörperschaften über 25 % – für o6_17 nicht förderfähig"}
}

access_violations contains v if {
	object.get(applicant, "is_active_farmer", true) == false
	v := {"rule_id": "O6_17-SRL-1.4-ACTIVE-FARMER", "message": "Förderwerbende Person ist kein aktiver Landwirt"}
}

# 1. Verpflichtungsjahr: bei Nichterfüllung kommt kein Vertrag zustande (SRL 1.12.1.1)
contract_established if {
	first_participation_year
	count(access_violations) == 0
}

# Ab dem 2. Verpflichtungsjahr: bei Nichterfüllung keine Prämie im betroffenen Jahr (SRL 1.12.1.1)
premium_blocked_by_access_conditions if count(access_violations) > 0

# Modul:
#   o6_17 – Förderverpflichtungen (Umbruchsverzicht, Weiterbildung, Bodenuntersuchung, AGL, Mindestbewirtschaftung)
package oepul.o6_17

# ---------------------------------------------------------------------------
# Verzicht auf Grünlandumbruch auf sämtlichen Grünlandflächen des Betriebes
# ---------------------------------------------------------------------------
conversion_events contains [pid, e] if {
	some p in parcels
	is_grassland(p)
	pid := p.parcel_id
	some e in object.get(p, ["operations", "grassland_conversions"], [])
}

# Geringfügige Abweichungen bis 300 m² je Einzelfläche gelten nicht als Umbruch
conversion_permitted(e) if {
	object.get(e, "kind", "") != "fill"
	e.area_m2 <= cfg.lists.minor_deviation_max_m2_per_area
}

# Aufschüttungen mit nachfolgender Einsaat; > 300 m² nur mit vorab eingeholter landesrechtlicher Bewilligung
conversion_permitted(e) if {
	e.kind == "fill"
	e.area_m2 <= cfg.lists.fill_permit_threshold_m2
}

conversion_permitted(e) if {
	e.kind == "fill"
	object.get(e, "reseeded", false) == true
	e.area_m2 > cfg.lists.fill_permit_threshold_m2
	object.get(e, "permit_obtained", false) == true
}

# Ausnahme: Grünlandsanierung nach Schädlingsbefall mit Dokumentation
conversion_permitted(e) if {
	e.reason == "pest_damage"
	object.get(e, "documented", false) == true
}

# Ausnahme: Neueinsaat regionaler Grünland-Saatgutmischung für Biodiversitätsflächen in UBB/BIO
conversion_permitted(e) if {
	e.reason == "biodiversity_reseeding"
	ubb_or_bio_participation
	object.get(e, "documented", false) == true
}

allowed_renewal_equipment := {r.key | some r in cfg.lists.allowed_renewal_equipment}

violations contains v if {
	some [pid, e] in conversion_events
	not conversion_permitted(e)
	v := {"rule_id": "O6_17-MB-6.1-NO-CONVERSION", "parcel_id": pid, "message": "Unzulässiger Grünlandumbruch während des Vertragszeitraums"}
}

violations contains v if {
	object.get(o617, "arable_grassland_swap", false) == true
	v := {"rule_id": "O6_17-MB-6.1-NO-ARABLE-GRASSLAND-SWAP", "parcel_id": null, "message": "Acker-Grünland-Flächentausch ist nicht möglich"}
}

violations contains v if {
	some p in parcels
	is_grassland(p)
	some equipment in object.get(p, ["operations", "renewal_equipment"], [])
	not equipment in allowed_renewal_equipment
	v := {"rule_id": "O6_17-MB-6.2-RENEWAL-EQUIPMENT", "parcel_id": p.parcel_id, "message": sprintf("Gerät %v ist für die umbruchslose Grünlanderneuerung nicht zulässig", [equipment])}
}

# ---------------------------------------------------------------------------
# Weiterbildung: 5 Stunden Grünlandbewirtschaftung bis 31.12.2025
# ---------------------------------------------------------------------------
training_cfg := cfg.lists.training

training_courses := object.get(o617, "training", [])

trained_person_still_counts(c) if object.get(c, "person_left_farm_date", null) == null

trained_person_still_counts(c) if {
	d := object.get(c, "person_left_farm_date", null)
	is_string(d)
	d >= training_cfg.deadline
}

creditable_course(c) if {
	c.course_date >= training_cfg.earliest_creditable_course_date
	c.course_date <= training_cfg.deadline
	object.get(c, "provider_recognized", false) == true
	object.get(c, "grassland_topic", false) == true
	object.get(c, "person_role", "") in {r | some r in training_cfg.eligible_person_roles}
	object.get(c, "credited_to_other_farm", false) == false
	object.get(c, "credited_to_other_obligation", false) == false
	trained_person_still_counts(c)
}

training_hours_creditable := sum([c.hours | some c in training_courses; creditable_course(c)])

training_obligation_met if training_hours_creditable >= training_cfg.required_hours

violations contains v if {
	deadline_passed(training_cfg.deadline)
	not training_obligation_met
	v := {"rule_id": "O6_17-MB-6.4-TRAINING", "parcel_id": null, "message": sprintf("Nur %v anrechenbare Weiterbildungsstunden (mindestens 5 bis 31.12.2025)", [training_hours_creditable])}
}

# ---------------------------------------------------------------------------
# Bodenuntersuchungen: je angefangene 5 ha förderfähiges Grünland < 18 % (MFA 2025) eine Probe
# ---------------------------------------------------------------------------
soil_cfg := cfg.lists.soil_sampling

soil_base_parcel(p) if {
	is_grassland(p)
	is_number(p.slope_percent)
	p.slope_percent < rates.slope_threshold_percent
	not gloez_conversion_ban(p)
}

soil_sample_base_ha := b if {
	b := object.get(o617, "eligible_grassland_lt18_mfa2025_ha", null)
	is_number(b)
}

soil_sample_base_ha := b if {
	not is_number(object.get(o617, "eligible_grassland_lt18_mfa2025_ha", null))
	application_year == soil_cfg.reference_application_year
	b := sum([p.area_ha | some p in parcels; soil_base_parcel(p)])
}

soil_samples_required := ceil(soil_sample_base_ha / soil_cfg.hectares_per_sample) if soil_sample_base_ha > 0

soil_samples_required := 0 if soil_sample_base_ha <= 0

soil_samples := object.get(o617, "soil_samples", [])

valid_soil_sample(s) if {
	s.drawn_date >= soil_cfg.earliest_creditable_sample_date
	s.lab_submission_date <= soil_cfg.deadline
	object.get(s, "lab_accredited", false) == true
	object.get(s, "method", "") in {m | some m in soil_cfg.allowed_methods}
	every param in soil_cfg.required_parameters {
		param in object.get(s, "parameters", [])
	}
	object.get(s, "received_with_transferred_land", false) == false
}

valid_soil_sample_count := count({s.sample_id | some s in soil_samples; valid_soil_sample(s)})

soil_sample_obligation_met if valid_soil_sample_count >= soil_samples_required

violations contains v if {
	deadline_passed(soil_cfg.deadline)
	is_number(soil_samples_required)
	not soil_sample_obligation_met
	v := {"rule_id": "O6_17-MB-6.5-SOIL-SAMPLES", "parcel_id": null, "message": sprintf("%v gültige Bodenproben, erforderlich %v", [valid_soil_sample_count, soil_samples_required])}
}

violations contains v if {
	some s in soil_samples
	valid_soil_sample(s)
	object.get(s, "entered_in_invekos_gis", false) == false
	v := {"rule_id": "O6_17-MB-6.5-SOIL-RESULTS-ENTRY", "parcel_id": null, "message": sprintf("Ergebnis der Bodenprobe %v nicht im INVEKOS-GIS erfasst", [s.sample_id])}
}

# ---------------------------------------------------------------------------
# Zuschlag AGL: beantragte Schläge ohne erfüllte Voraussetzungen
# ---------------------------------------------------------------------------
violations contains v if {
	some p in parcels
	field_use_attr(p, "agl_requires_code_and_survey") == true
	cfg.lists.agl.code in parcel_codes(p)
	not agl_conditions_met(p)
	v := {"rule_id": "O6_17-MB-6.6-AGL-CONDITIONS", "parcel_id": p.parcel_id, "message": "Code AGL ohne erfüllte Kennarten-, Erstnutzungs- oder Dokumentationsauflagen"}
}

violations contains v if {
	some p in parcels
	cfg.lists.agl.code in parcel_codes(p)
	field_use_attr(p, "agl_requires_code_and_survey") == false
	v := {"rule_id": "O6_17-MB-7-AGL-CODE-USE-TYPES", "parcel_id": p.parcel_id, "message": "Code AGL nur auf Mähwiese/-weide zwei bzw. drei und mehr Nutzungen vorgesehen"}
}

# ---------------------------------------------------------------------------
# Mindestbewirtschaftung auf Grünland (jährlich Mahd mit Verbringung oder vollflächige Beweidung)
# ---------------------------------------------------------------------------
grassland_minimum_management_met(p) if count(object.get(p, ["operations", "cutting_dates"], [])) > 0

grassland_minimum_management_met(p) if object.get(p, ["operations", "full_grazing"], false) == true

grassland_minimum_management_met(p) if {
	field_use_attr(p, "is_bergmaehder") == true
	last := object.get(p, ["operations", "last_full_mowing_year"], null)
	is_number(last)
	application_year - last < 2
}

violations contains v if {
	some p in parcels
	base_premium_eligible(p)
	not grassland_minimum_management_met(p)
	v := {"rule_id": "O6_17-SRL-1.6.3.3-MIN-MANAGEMENT", "parcel_id": p.parcel_id, "message": "Mindestbewirtschaftung Grünland (Mahd mit Verbringung oder Beweidung) nicht erfüllt"}
}

package oepul.o6_17_test

import data.oepul.o6_17

# ---------------------------------------------------------------------------
# Basis-Fixture: tierhaltender Grünlandbetrieb, Einstieg 2025, Teilnahme UBB
# ---------------------------------------------------------------------------
kennarten_5 := ["Wiesen-Salbei", "Hornklee", "Wiesen-Margerite", "Ochsenauge", "Briza media"]

base_parcels := [
	{
		"parcel_id": "P1", "area_ha": 6, "land_use": "grassland", "slope_percent": 10,
		"grassland_figure": 35, "field_use_type": "maehwiese_weide_3plus", "codes": [],
		"operations": {"cutting_dates": ["2025-05-20"], "first_use_type": "mowing"},
	},
	{
		"parcel_id": "P2", "area_ha": 4, "land_use": "grassland", "slope_percent": 25,
		"grassland_figure": 25, "field_use_type": "einmaehdige_wiese", "codes": [],
		"operations": {"cutting_dates": ["2025-07-10"], "first_use_type": "mowing"},
	},
	{
		"parcel_id": "P3", "area_ha": 2, "land_use": "grassland", "slope_percent": 5,
		"grassland_figure": 45, "field_use_type": "maehwiese_weide_2", "codes": ["AGL"],
		"operations": {"cutting_dates": ["2025-06-01"], "first_use_type": "mowing"},
		"agl_survey": {"documented": true, "sections": [{"kennarten": kennarten_5}, {"kennarten": kennarten_5}]},
	},
	{"parcel_id": "P4", "area_ha": 3, "land_use": "arable", "slope_percent": 3, "field_use_type": "kleegras"},
	{"parcel_id": "P5", "area_ha": 5, "land_use": "arable", "slope_percent": 3, "field_use_type": "weizen"},
]

base_input := {
	"farm": {"year": 2025},
	"land": {"total_area_ha": 20, "alpine_pasture_area_ha": 0, "parcels": base_parcels},
	"livestock": {"species_groups": [{"species": "cattle", "rgve_category": "cattle_ge_2y", "animal_count": 5}]},
	"oepul": {
		"participating_measures": ["UBB", "O6_17"],
		"first_oepul_year": 2023,
		"applicant": {"applicant_type": "natural_person", "public_body_share": 0, "is_active_farmer": true},
		"o6_17": {
			"contract_start_year": 2025,
			"measure_application_date": "2024-12-10",
			"eligible_grassland_lt18_mfa2025_ha": 8,
			"soil_samples": [
				{"sample_id": "S1", "drawn_date": "2024-10-01", "lab_submission_date": "2024-10-02", "lab_accredited": true, "method": "richtlinien_sachgerechte_duengung", "parameters": ["ph", "phosphorus", "potassium", "humus"], "entered_in_invekos_gis": true},
				{"sample_id": "S2", "drawn_date": "2025-03-01", "lab_submission_date": "2025-03-05", "lab_accredited": true, "method": "euf", "parameters": ["ph", "phosphorus", "potassium", "humus"], "entered_in_invekos_gis": true},
			],
			"training": [{"hours": 5, "course_date": "2024-02-01", "provider_recognized": true, "grassland_topic": true, "person_role": "applicant"}],
		},
	},
}

with_parcels(ps) := object.union(base_input, {"land": {"total_area_ha": 20, "alpine_pasture_area_ha": 0, "parcels": ps}})

with_o617(extra) := object.union(base_input, {"oepul": object.union(base_input.oepul, {"o6_17": object.union(base_input.oepul.o6_17, extra)})})

r2(x) := round(x * 100) / 100

# ---------------------------------------------------------------------------
# Zugangsvoraussetzungen
# ---------------------------------------------------------------------------
test_base_case_contract_established if {
	o6_17.contract_established with input as base_input
	count(o6_17.access_violations) == 0 with input as base_input
}

test_livestock_density_counts_grassland_and_arable_forage if {
	o6_17.forage_area_ha == 15 with input as base_input
	r2(o6_17.livestock_density_rgve_per_ha) == 0.33 with input as base_input
	o6_17.is_livestock_farm with input as base_input
}

test_not_livestock_farm_first_year if {
	inp := object.union(base_input, {"livestock": {"species_groups": [{"rgve_category": "cattle_ge_2y", "animal_count": 4}]}})
	not o6_17.is_livestock_farm with input as inp
	some v in o6_17.access_violations with input as inp
	v.rule_id == "O6_17-MB-3.4-LIVESTOCK-FIRST-YEAR"
}

test_pigs_do_not_count_as_rgve if {
	inp := object.union(base_input, {"livestock": {"species_groups": [{"rgve_category": "breeding_sows_ge_50kg", "animal_count": 100}]}})
	o6_17.rgve_total == 0 with input as inp
}

test_animals_abroad_not_counted if {
	inp := object.union(base_input, {"livestock": {"species_groups": [{"rgve_category": "cattle_ge_2y", "animal_count": 5, "kept_in_austria": false}]}})
	o6_17.rgve_total == 0 with input as inp
}

test_livestock_only_required_in_first_year if {
	inp := object.union(base_input, {"farm": {"year": 2026}, "livestock": {"species_groups": []}})
	not o6_17.first_participation_year with input as inp
	count(o6_17.access_violations) == 0 with input as inp
